import{_ as i,o as t,c as o,a2 as e}from"./chunks/framework.CdvW4CUT.js";const d=JSON.parse('{"title":"🔧 伺服規定 2021-08-21","description":"","frontmatter":{},"headers":[],"relativePath":"rule/history/20210821/index.md","filePath":"rule/history/20210821.md"}'),n={name:"rule/history/20210821/index.md"};function r(s,l,a,u,_,f){return t(),o("div",null,[...l[0]||(l[0]=[e('<h1 id="伺服規定-2021-08-21" tabindex="-1">🔧 伺服規定 2021-08-21 <a class="header-anchor" href="#伺服規定-2021-08-21" aria-label="Permalink to &quot;:wrench: 伺服規定 2021-08-21&quot;">​</a></h1><ul><li><strong><font size="4">請勿影響其他玩家遊玩</font></strong><ul><li>破壞建築、偷東西、騷擾、詐欺、惡意誤導、無意義LAG機...等影響他人的行為</li><li>基本上，在路上看到人造建築與箱子不要任意去亂碰</li><li>若遊玩上有糾紛，將斟酌雙方提出的資訊，由伺服人員做裁定與懲處</li></ul></li><li><strong><font size="4">嚴禁任何外掛行為</font></strong><ul><li>如果有使用一些客觀上<strong>有疑慮</strong>是否外掛的模組 請務必先以客服詢問，否則將依照伺服人員認定之處分</li><li>以下幾種可使用： 小地圖、整理背包、光影、藍圖(Litematica)[活動時禁止使用] 其餘模組若要使用 請詢問客服</li></ul></li><li><strong><font size="4">請勿使用遊戲 bug</font></strong><ul><li>例如:TNT、鐵軌、地毯複製機...</li></ul></li><li><strong><font size="4">請勿開分身或使用VPN遊玩</font></strong><ul><li>有此需求請一律由客服詢問或申請，否則將依照伺服人員認定處分</li></ul></li><li><strong><font size="4">嚴禁盜取或複製他人的畫作</font></strong><ul><li>違規者視情況給予處分</li></ul></li></ul><ol><li>伺服處分以帳號與IP為準，請務必保管好個人帳號 (切勿外借給任何人，若發生任何狀況須自行承擔責任) 不接受任何因個人因素導致之理由作為要求解除處分之依據</li><li>當你發現有玩家有違反以上規定時 請將狀況回報至Discord，交由管理員處理 (切勿知情不報)</li><li>若對於規定有任何疑慮的部分 請務必先詢問伺服人員，否則將依照伺服人員的認定方式處理</li></ol>',3)])])}const g=i(n,[["render",r]]);export{d as __pageData,g as default};
